    intro: { en: 'Find the part of your journey that needs clarity. Each matter begins with fit, evidence and an honest view of the path ahead.', ta: 'உங்கள் பயணத்தில் தெளிவு தேவைப்படும் பகுதியைக் கண்டறியுங்கள். ஒவ்வொரு விவகாரமும் பொருத்தம், ஆதாரம் மற்றும் முன்னால் உள்ள பாதையின் நேர்மையான பார்வையுடன் தொடங்குகிறது.', hi: 'अपनी यात्रा के उस हिस्से को खोजें जिसे स्पष्टता चाहिए। प्रत्येक मामला उपयुक्तता, साक्ष्य और आगे के मार्ग के ईमानदार दृष्टिकोण से शुरू होता है।' },
    t1: { en: 'Refugee Claims', ta: 'அகதி கோரிக்கைகள்', hi: 'शरणार्थी दावे' },
    x1: { en: 'Refugee claims, admissibility hearings and protection submissions.', ta: 'அகதி கோரிக்கைகள், அனுமதிப்பு விசாரணைகள் மற்றும் பாதுகாப்பு சமர்ப்பிப்புகள்.', hi: 'शरणार्थी दावे, प्रवेशयोग्यता सुनवाई और सुरक्षा प्रस्तुतीकरण।' },
    f1: { en: 'Basis of claim · hearing · evidence', ta: 'கோரிக்கை அடிப்படை · விசாரணை · ஆதாரம்', hi: 'दावा आधार · सुनवाई · साक्ष्य' },
    t2: { en: 'Refusals & Appeals', ta: 'நிராகரிப்புகள் & மேல்முறையீடுகள்', hi: 'अस्वीकृतियाँ और अपील' },
    x2: { en: 'IAD matters, refused applications and strategic case review.', ta: 'IAD விவகாரங்கள், நிராகரிக்கப்பட்ட விண்ணப்பங்கள் மற்றும் மூலோபாய வழக்கு மதிப்பாய்வு.', hi: 'IAD मामले, अस्वीकृत आवेदन और रणनीतिक मामला समीक्षा।' },
    f2: { en: 'Deadlines · remedy · evidentiary record', ta: 'காலக்கெடு · தீர்வு · ஆதார பதிவு', hi: 'समय सीमा · उपचार · साक्ष्य रिकॉर्ड' },
    t3: { en: 'Humanitarian & Compassionate', ta: 'மனிதநேய & கருணை', hi: 'मानवीय और करुणामय' },
    x3: { en: 'Human-centred submissions grounded in establishment, hardship and the best interests of children.', ta: 'நிலைநிறுத்தல், துன்பம் மற்றும் குழந்தைகளின் சிறந்த நலன்களில் வேரூன்றிய மனிதநேய சமர்ப்பிப்புகள்.', hi: 'स्थापना, कष्ट और बच्चों के सर्वोत्तम हित में निहित मानव-केंद्रित प्रस्तुतीकरण।' },
    f3: { en: 'Establishment · hardship · child\u2019s interests', ta: 'நிலைநிறுத்தல் · துன்பம் · குழந்தையின் நலன்கள்', hi: 'स्थापना · कष्ट · बच्चे का हित' },
    t4: { en: 'Family Sponsorships', ta: 'குடும்ப ஸ்பான்சர்ஷிப்கள்', hi: 'परिवार प्रायोजन' },
    x4: { en: 'Spousal, partner, child, parent and grandparent pathways.', ta: 'துணை, பங்காளி, குழந்தை, பெற்றோர் மற்றும் தாத்தா பாட்டி பாதைகள்.', hi: 'पति/पत्नी, साथी, बच्चे, माता-पिता और दादा-दादी मार्ग।' },
    f4: { en: 'Eligibility · relationship evidence · admissibility', ta: 'தகுதி · உறவு ஆதாரம் · அனுமதிப்புத்தன்மை', hi: 'पात्रता · संबंध साक्ष्य · प्रवेशयोग्यता' },
    t5: { en: 'Employers', ta: 'தொழிலாளர்', hi: 'नियोक्ता' },
    x5: { en: 'LMIA processing, work permits and compliance for Canadian businesses hiring globally.', ta: 'LMIA செயலாக்கம், பணி அனுமதிகள் மற்றும் உலகளாவிய நியமனத்திற்கான கனடிய வணிகங்களுக்கான இணக்கம்.', hi: 'LMIA प्रसंस्करण, कार्य परमिट और वैश्विक रूप से काम पर रखने वाले कनाडाई व्यवसायों के लिए अनुपालन।' },
    f5: { en: 'LMIA · work permits · compliance', ta: 'LMIA · பணி அனுமதிகள் · இணக்கம்', hi: 'LMIA · कार्य परमिट · अनुपालन' },
    t6: { en: 'Entrepreneurs & Aspiring Entrepreneurs', ta: 'தொழில்முனைவோர் & எதிர்கால தொழில்முனைவோர்', hi: 'उद्यमी और भावी उद्यमी' },
    x6: { en: 'Business and provincial entrepreneur pathways for founders and operators.', ta: 'நிறுவனர்கள் மற்றும் இயக்குனர்களுக்கான தொழில் மற்றும் மாகாண தொழில்முனைவோர் பாதைகள்.', hi: 'संस्थापकों और संचालकों के लिए व्यवसाय और प्रांतीय उद्यमी मार्ग।' },
    f6: { en: 'Experience · net worth · business plan', ta: 'அனுபவம் · நிகர மதிப்பு · தொழில் திட்டம்', hi: 'अनुभव · कुल मूल्य · व्यवसाय योजना' },
    t7: { en: 'Healthcare Worker Pathways', ta: 'சுகாதார தொழிலாளர் பாதைகள்', hi: 'स्वास्थ्य सेवा कर्मचारी मार्ग' },
    x7: { en: 'Foreign-trained health care professionals and credential recognition pathways.', ta: 'வெளிநாட்டில் பயிற்சி பெற்ற சுகாதார நிபுணர்கள் மற்றும் தகுதிசான்று அங்கீகார பாதைகள்.', hi: 'विदेश में प्रशिक्षित स्वास्थ्य सेवा पेशेवर और प्रत्यायन मान्यता मार्ग।' },
    f7: { en: 'LMIA · credential transfer · work permits', ta: 'LMIA · தகுதிசான்று மாற்றம் · பணி அனுமதிகள்', hi: 'LMIA · प्रत्यायन स्थानांतरण · कार्य परमिट' },
