    location: { en: 'Markham, Ontario', ta: 'மார்க்ஹாம், ஒன்டாரியோ', hi: 'मार्कहैम, ओंटारियो' },
    hours: { en: 'Evening & Weekend consults', ta: 'மாலை & வார இறுதி ஆலோசனைகள்', hi: 'शाम और सप्ताहांत परामर्श' },
    langs: { en: 'English · தமிழ் · हिंदी', ta: 'ஆங்கிலம் · தமிழ் · ஹிந்தி', hi: 'अंग्रेज़ी · तमिल · हिंदी' },
