    q1: { en: 'What best describes your situation?', ta: 'உங்கள் நிலையை எது சிறப்பாக விவரிக்கிறது?', hi: 'आपकी स्थिति को क्या सबसे अच्छा वर्णन करता है?' },
    q1o1: { en: 'I received a refusal or face an appeal', ta: 'நான் நிராகரிப்பு பெற்றேன் அல்லது மேல்முறையீடு உள்ளது', hi: 'मुझे अस्वीकृति मिली या अपील है' },
    q1o2: { en: 'I want to sponsor a family member', ta: 'நான் குடும்ப உறுப்பினரை ஸ்பான்சர் செய்ய விரும்புகிறேன்', hi: 'मैं परिवार के सदस्य को प्रायोजित करना चाहता हूँ' },
    q1o3: { en: 'I am seeking protection in Canada', ta: 'நான் கனடாவில் பாதுகாப்பு நாடுகிறேன்', hi: 'मैं कनाडा में सुरक्षा चाहता हूँ' },
    q1o4: { en: 'I want to live in Canada permanently', ta: 'நான் கனடாவில் நிரந்தரமாக வாழ விரும்புகிறேன்', hi: 'मैं कनाडा में स्थायी रूप से रहना चाहता हूँ' },
    q1o5: { en: 'I am an employer hiring from abroad', ta: 'நான் வெளிநாட்டிலிருந்து தொழிலாளர் நியமிக்கிறேன்', hi: 'मैं विदेश से कर्मचारी नियुक्त करता हूँ' },
    q1o6: { en: 'I want to start or buy a business', ta: 'நான் தொழில் தொடங்க அல்லது வாங்க விரும்புகிறேன்', hi: 'मैं व्यवसाय शुरू या खरीदना चाहता हूँ' },
    q1o7: { en: 'I need a permit, visa, or renewal', ta: 'எனக்கு அனுமதி, விசா அல்லது புதுப்பிப்பு தேவை', hi: 'मुझे परमिट, वीज़ा या नवीनीकरण चाहिए' },
    q1o8: { en: 'I am a healthcare worker', ta: 'நான் சுகாதார தொழிலாளர்', hi: 'मैं स्वास्थ्य सेवा कर्मी हूँ' },
    q2: { en: 'Where are you in the process?', ta: 'செயல்முறையில் நீங்கள் எங்கே இருக்கிறீர்கள்?', hi: 'प्रक्रिया में आप कहाँ हैं?' },
    q2o1: { en: 'Just exploring options', ta: 'விருப்பங்களை ஆராய்கிறேன்', hi: 'केवल विकल्प खोज रहा हूँ' },
    q2o2: { en: 'Preparing an application', ta: 'விண்ணப்பம் தயாரிக்கிறேன்', hi: 'आवेदन तैयार कर रहा हूँ' },
    q2o3: { en: 'Waiting on a decision', ta: 'முடிவுக்காக காத்திருக்கிறேன்', hi: 'निर्णय का इंतज़ार कर रहा हूँ' },
    q2o4: { en: 'I already have a refusal', ta: 'எனக்கு ஏற்கனவே நிராகரிப்பு உள்ளது', hi: 'मेरे पास पहले से अस्वीकृति है' },
